package main

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/store"
)

// TestSweepDemotion pins the completion-driven demotion executor (eviction
// task 1.2, the Completion-driven demotion delta): every build directory of
// a fully-watched serial's episode dies through the existing evictDir
// vocabulary and the item's packaging record resets to none — complete and
// partial named builds alike, since a demoted partial must replay through
// pack-on-play, which requires none; a serial with an unwatched tail (its
// ids never enter the demote list) loses nothing; and the bytes the demotion
// frees count in the same pass's budget accounting — newSweep positions the
// executor before sweepBudget, so a within-budget disk after the pass (where
// the pre-demotion disk was over it) is the behavioral proof of the order.
// The fully-watched judgment itself is the policy's (TestFrontierDemote);
// these cases drive the shell's executor on its demote return.
func TestSweepDemotion(t *testing.T) {
	// demotionSeed seeds one live item per docs key and returns the store,
	// its context, and an empty artifact root.
	demotionSeed := func(t *testing.T, docs map[string]map[string]any) (*store.Store, context.Context, string) {
		t.Helper()
		ctx := context.Background()
		st, err := store.Open(ctx, filepath.Join(t.TempDir(), "demotion.db"))
		if err != nil {
			t.Fatalf("store.Open: %v", err)
		}
		t.Cleanup(func() { _ = st.Close() })
		libID, err := st.CreateLibrary(ctx, "tv", "/media/demotion", "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		for id, doc := range docs {
			raw, err := json.Marshal(doc)
			if err != nil {
				t.Fatalf("marshal doc %s: %v", id, err)
			}
			if err := st.PutItem(ctx, store.Item{
				ID: id, ModuleID: "tv", LibraryID: libID, FileID: id,
				RelativePath: id + ".mkv", MediaType: "tv",
				Document: raw, SchemaVersion: 1,
			}); err != nil {
				t.Fatalf("PutItem %s: %v", id, err)
			}
		}
		return st, ctx, filepath.Join(t.TempDir(), "streams")
	}

	// demotionBuild lays down one build directory holding one segment of
	// exactly size bytes (real bytes — the budget case reads them as disk
	// truth through dirSize).
	demotionBuild := func(t *testing.T, root, itemID, name string, size int64) string {
		t.Helper()
		p := filepath.Join(root, itemID, name)
		if err := os.MkdirAll(p, 0o755); err != nil {
			t.Fatalf("mkdir %s: %v", p, err)
		}
		if err := os.WriteFile(filepath.Join(p, "seg0.ts"), make([]byte, size), 0o644); err != nil {
			t.Fatalf("write segment in %s: %v", p, err)
		}
		return p
	}

	// demotionStreams builds an item document whose streams namespace names
	// its build nonce in the given state (the reset's named-build check
	// reads exactly this shape — playlist included, as the lane persists it).
	demotionStreams := func(state, nonce string) map[string]any {
		return map[string]any{
			"streams": map[string]any{
				"state":    state,
				"nonce":    nonce,
				"playlist": "/media/itm/" + nonce + "/index.m3u8",
			},
		}
	}

	// demotionDoc re-reads one item's document off the store.
	demotionDoc := func(t *testing.T, ctx context.Context, st *store.Store, id string) map[string]any {
		t.Helper()
		row, err := st.GetItem(ctx, id, access.System())
		if err != nil {
			t.Fatalf("GetItem %s: %v", id, err)
		}
		return decodeItemDoc(row.Document)
	}

	// demotionState reads one item's streams state back.
	demotionState := func(t *testing.T, ctx context.Context, st *store.Store, id string) string {
		t.Helper()
		streams, _ := demotionDoc(t, ctx, st, id)["streams"].(map[string]any)
		state, _ := streams["state"].(string)
		return state
	}

	// gone reports whether one build directory is off the disk.
	gone := func(root, itemID, nonce string) bool {
		_, err := os.Stat(filepath.Join(root, itemID, nonce))
		return os.IsNotExist(err)
	}

	t.Run("fully watched serial's builds evicted and the record resets to none", func(t *testing.T) {
		// The named build and a stale sibling both die; the complete-state
		// record's whole streams namespace resets to none — no stale
		// playlist or nonce may name a build the disk lacks.
		st, ctx, root := demotionSeed(t, map[string]map[string]any{
			"itm_fw": demotionStreams("complete", "n1"),
		})
		demotionBuild(t, root, "itm_fw", "n1", 512)
		demotionBuild(t, root, "itm_fw", "n2", 512)
		sweepDemotion(ctx, st, root, []string{"itm_fw"}, nil)
		for _, nonce := range []string{"n1", "n2"} {
			if !gone(root, "itm_fw", nonce) {
				t.Fatalf("build %s survived demotion", nonce)
			}
		}
		if state := demotionState(t, ctx, st, "itm_fw"); state != "none" {
			t.Fatalf("streams state = %q, want none", state)
		}
		streams, _ := demotionDoc(t, ctx, st, "itm_fw")["streams"].(map[string]any)
		if _, ok := streams["nonce"]; ok {
			t.Fatalf("streams nonce survived the reset: %v", streams)
		}
	})

	t.Run("mixed serial untouched", func(t *testing.T) {
		// An id outside the demote list (a serial with an unwatched tail)
		// loses nothing: its builds stay and its record keeps naming them.
		st, ctx, root := demotionSeed(t, map[string]map[string]any{
			"itm_mx": demotionStreams("complete", "n1"),
		})
		demotionBuild(t, root, "itm_mx", "n1", 512)
		sweepDemotion(ctx, st, root, []string{"itm_other"}, nil)
		if gone(root, "itm_mx", "n1") {
			t.Fatal("un-demoted serial's build was evicted")
		}
		if state := demotionState(t, ctx, st, "itm_mx"); state != "complete" {
			t.Fatalf("streams state = %q, want complete", state)
		}
		streams, _ := demotionDoc(t, ctx, st, "itm_mx")["streams"].(map[string]any)
		if nonce, _ := streams["nonce"].(string); nonce != "n1" {
			t.Fatalf("streams nonce = %q, want n1", nonce)
		}
	})

	t.Run("partial named build resets to none", func(t *testing.T) {
		// The reset reaches partial on the demotion path — the budget path's
		// complete-only contract does not — so a demoted partial replays
		// through pack-on-play, which requires none.
		st, ctx, root := demotionSeed(t, map[string]map[string]any{
			"itm_pt": demotionStreams("partial", "p1"),
		})
		demotionBuild(t, root, "itm_pt", "p1", 512)
		sweepDemotion(ctx, st, root, []string{"itm_pt"}, nil)
		if !gone(root, "itm_pt", "p1") {
			t.Fatal("partial build survived demotion")
		}
		if state := demotionState(t, ctx, st, "itm_pt"); state != "none" {
			t.Fatalf("streams state = %q, want none", state)
		}
	})

	t.Run("freed bytes count in the same pass's budget accounting", func(t *testing.T) {
		// Demotion runs before sweepBudget in the pass: the fully-watched
		// item's 4 KiB frees the pass before the budget (4 KiB) reads the
		// disk, so the 2 KiB keep-build survives — without the demotion
		// pass's ordering, the stampless keep build sorts oldest and the
		// LRU would evict it to fit.
		st, ctx, root := demotionSeed(t, map[string]map[string]any{
			"itm_fw": demotionStreams("complete", "big"),
			"itm_kp": demotionStreams("complete", "keep"),
		})
		demotionBuild(t, root, "itm_fw", "big", 4096)
		demotionBuild(t, root, "itm_kp", "keep", 2048)
		if _, err := st.PutProgress(ctx, "itm_fw", 100, access.System()); err != nil {
			t.Fatalf("PutProgress: %v", err)
		}
		const budget int64 = 4096
		sweepDemotion(ctx, st, root, []string{"itm_fw"}, nil)
		sweepBudget(ctx, st, root, budget, nil, nil)
		if !gone(root, "itm_fw", "big") {
			t.Fatal("fully-watched build survived the pass")
		}
		if gone(root, "itm_kp", "keep") {
			t.Fatal("budget accounting ignored the demotion's freed bytes — the keep build was evicted")
		}
		if used := dirSize(root); used > budget {
			t.Fatalf("post-pass disk usage = %d, want <= budget %d", used, budget)
		}
	})
}
